int sockfd;
char buffer[512];
struct sockaddr_storage sender_info;
socklen_t addr_len = sizeof(sender_info);
ssize_t bytes_received;

// Receive data, storing sender address in sender_info
bytes_received = recvfrom(
    sockfd,
    buffer, sizeof(buffer),
    0, // Flags (e.g., MSG_WAITALL)
    (struct sockaddr *)&sender_info,
    &addr_len
);

if (bytes_received > 0) {
    // Success: bytes_received holds count
} else if (bytes_received == -1) {
    // Error handling
}
